algorithms.pseudocode:
function decide_simulation(a, b, max_exp, n_max):
    for c in 0 .. max_exp:
        define f_c(m) = (m + 2)^c - 1
        if is_poly_mono(f_c, c, n_max):           # monotone and f_c(n)+1 <= (n+2)^c
            if for all n in 0..n_max: a(n) <= f_c(b(n)):
                return (c, witness "f(m) = (m+2)^c - 1")
    return NONE   # no polynomial domination found -> evidence of separation

function is_poly_mono(f, k, n_max):
    prev <- f(0)
    for n in 0 .. n_max:
        cur <- f(n)
        if cur < prev or cur + 1 > (n + 2)^k: return false
        prev <- cur
    return true
